import{_ as o,o as t,c as d,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"鉴权与权限模型","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/auth.md","filePath":"advanced/auth.md","lastUpdated":1793354072000}'),c={name:"advanced/auth.md"};function a(s,e,n,i,l,h){return t(),d("div",null,[...e[0]||(e[0]=[r(`<h1 id="鉴权与权限模型" tabindex="-1">鉴权与权限模型 <a class="header-anchor" href="#鉴权与权限模型" aria-label="Permalink to &quot;鉴权与权限模型&quot;">​</a></h1><p>身份如何确认、权限如何分配，以及前端在登录态未确定时如何取舍。</p><h2 id="token-体系" tabindex="-1">Token 体系 <a class="header-anchor" href="#token-体系" aria-label="Permalink to &quot;Token 体系&quot;">​</a></h2><p>两个 JWT 做身份认证，实现在 <code>backend-go/internal/auth</code>。</p><table tabindex="0"><thead><tr><th>Token</th><th>默认有效期</th><th>环境变量</th><th>通道</th></tr></thead><tbody><tr><td>Access（正式用户）</td><td><strong>1 小时</strong></td><td><code>JWT_ACCESS_EXPIRES_IN</code></td><td>httpOnly Cookie + Bearer 头 + query <code>token</code></td></tr><tr><td>Refresh（正式用户）</td><td><strong>30 天</strong></td><td><code>JWT_REFRESH_EXPIRES_IN</code></td><td>httpOnly Cookie（<code>POST /refresh</code> 也接受 body）</td></tr><tr><td>Access（guest）</td><td>1 小时</td><td>—</td><td>同上</td></tr><tr><td>Refresh（guest）</td><td>7 天</td><td>—</td><td>同上</td></tr></tbody></table><ul><li>payload 为 <code>{ userId, role, username?, iat }</code>。</li><li><strong>三种传递方式各对应一类场景</strong>：<code>extractAccessToken</code> 依次查 query <code>token</code>、cookie <code>access_token</code>、<code>Authorization: Bearer</code>。REST 能自由设头，用 Bearer；<code>&lt;video&gt;</code> / <code>&lt;audio&gt;</code> / MSE / hls.js 加不了自定义头，只能在媒体 URL 挂 <code>?token=</code>；Socket.IO 读不到 URL 之外的信息，从 cookie 或 <code>handshake.auth.token</code> 取。前端 <code>appendAuthToken()</code> 只对本站 <code>/api/</code> 路径附加 token，处理 HTTP 下没有 auth cookie 的场景。</li><li><strong>密钥自举</strong>：<code>loadOrCreateSecret</code> 按「环境变量 → <code>config/jwt-secrets.json</code>（长度 ≥32 才采信）→ 自动生成 64 位 hex 写回」三级回退。首次启动无需配置，生产建议显式设置。</li><li><strong>refresh 不轮换</strong>：<code>/refresh</code> 只重签 access token 并重写 cookie。</li><li><strong>令牌吊销</strong>：<code>User.tokenInvalidBefore</code> 早于该时间戳的令牌一律失效（<code>iat*1000 &lt; invalidBefore</code> 返回 401）。改密、删用户后调用 <code>invalidateUserTokens()</code> 写库并刷新内存缓存（TTL 60s，改密路径主动写缓存）。游客（userId=0）无 User 行，跳过检查。</li></ul><h3 id="cookie-属性与内网穿透兜底" tabindex="-1">Cookie 属性与内网穿透兜底 <a class="header-anchor" href="#cookie-属性与内网穿透兜底" aria-label="Permalink to &quot;Cookie 属性与内网穿透兜底&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td>同站 / 任意协议</td><td><code>sameSite: &#39;lax&#39;</code>（HTTPS 时加 <code>secure</code>）</td></tr><tr><td>跨站 + HTTPS</td><td><code>sameSite: &#39;none&#39;, secure: true</code></td></tr><tr><td>跨站 + HTTP</td><td><strong>无解</strong>（SameSite=None 必须 Secure），需同站反代或升级 HTTPS</td></tr><tr><td>HTTP 请求</td><td><strong>不下发 cookie</strong>，统一走 Bearer</td></tr></tbody></table><p><code>isRequestSecure</code> 依次用三个线索判断：<code>req.secure</code>、<code>X-Forwarded-Proto</code> 第一段是否为 <code>https</code>、<code>Origin</code> 是否以 <code>https://</code> 开头。最后一条是给内网穿透和 HTTP 反代 HTTPS 的兜底；伪造 <code>Origin</code> 只会导致对 http 连接下发 Secure cookie，浏览器直接丢弃。跨站判定按 schemeful same-site 规则并忽略端口，兼容端口映射。</p><h2 id="注册模式与游客" tabindex="-1">注册模式与游客 <a class="header-anchor" href="#注册模式与游客" aria-label="Permalink to &quot;注册模式与游客&quot;">​</a></h2><ul><li><strong>注册模式</strong>：<code>open</code> 注册即激活；<code>approval</code>（默认）注册后为 pending 需审核；<code>closed</code> 关闭注册。</li><li><strong>用户名与密码</strong>：用户名匹配 <code>/^[\\u4e00-\\u9fa5A-Za-z0-9_\\- ]{2,24}$/</code>，密码至少 4 位。<code>approval</code> 模式下 pending 用户登录与 refresh 均返回 403「账号正在审核中」；root 审核通过后置为 active，原角色为 guest 则提升为 user。</li><li><strong>游客</strong>：<code>POST /api/auth/guest</code> 无需鉴权，直接签发 <code>userId=0, role=&#39;guest&#39;</code>，<code>/auth/me</code> 返回虚拟用户而不查库。游客 refresh 7d 短于正式用户 30d，在无凭证可吊销的场景下压低滥用面。</li><li><strong>默认密码检测</strong>：登录响应带 <code>mustChangePassword</code>，由 bcrypt 比对 <code>&#39;root&#39;</code> 得出。</li><li><strong>限流</strong>：登录每 IP 15 分钟 20 次；改密每用户 1 分钟 3 次。</li></ul><h2 id="角色模型" tabindex="-1">角色模型 <a class="header-anchor" href="#角色模型" aria-label="Permalink to &quot;角色模型&quot;">​</a></h2><p>两层叠加：全局角色决定账号身份，房间运行时角色决定在某个房间里能做什么。</p><h3 id="全局角色" tabindex="-1">全局角色 <a class="header-anchor" href="#全局角色" aria-label="Permalink to &quot;全局角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>权限</th></tr></thead><tbody><tr><td><code>root</code></td><td>全部房间控制 / 删除、用户审核与角色管理、系统设置、更新、服务器文件</td></tr><tr><td><code>admin</code></td><td>创建并完全控制自己的房间；管理后台只读（不能删他人房间）</td></tr><tr><td><code>user</code></td><td>加入房间观看、评论弹幕（审核通过后）</td></tr><tr><td><code>guest</code></td><td>同 user（未登录或 pending）</td></tr></tbody></table><p>HTTP 侧管理路由统一挂 <code>authenticateToken + adminOnly</code>（root 与 admin 放行），root-only 端点用 <code>requireRoot</code>。改角色只允许在 <code>admin</code> 与 <code>user</code> 之间，root 不可改；root 判定同时看 <code>role===&#39;root&#39;</code> 或 <code>username===&#39;root&#39;</code>。</p><h3 id="房间运行时角色-叠加" tabindex="-1">房间运行时角色（叠加） <a class="header-anchor" href="#房间运行时角色-叠加" aria-label="Permalink to &quot;房间运行时角色（叠加）&quot;">​</a></h3><p>房主不是持久化角色，而是运行时角色：Session 表中 <code>role: &#39;sharer&#39; &amp;&amp; endedAt IS NULL</code> 的会话即当前房主。<code>canViewerPerform</code> 按固定顺序判定：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>房主（短路 true） → root（true） → 房管（查矩阵 moderator）</span></span>
<span class="line"><span>→ admin（查矩阵 admin） → user（查矩阵 user） → guest（false）</span></span></code></pre></div><ul><li><strong>权限矩阵</strong>：系统设置里的矩阵覆盖 <code>addMovie / manageMovie / musicQueue / kickViewer / muteViewer</code> 五个动作与 <code>moderator / admin / user</code> 三列，缺省为房管与 admin 允许、user 拒绝。前端镜像同一份矩阵做 UI 门控（<code>systemSettingsStore.canRoomViewerPerform</code>）。</li><li><strong>房管（上限 10 名）</strong>：目标须为登录用户、非房主本人、当前在房间内；名单以 JSON 数组存在 <code>Room.moderators</code>。防篡权规则 <code>canModeratorActOn</code>：不能操作房主、其他房管与 root。</li><li><strong>权限校验缓存</strong>：5 秒 TTL（容量 1000），踢出、转交、会话结束时主动失效。</li><li><strong>Socket 侧身份</strong>：角色取自握手写入的 <code>socket.data.userId / role / username</code>，不可伪造；控制申请事件里的 <code>from</code> 由服务端注入。</li><li><strong>建房权限</strong>：guest 恒否；root / admin 恒是；user 取决于 <code>roomCreationMode === &#39;all-users&#39;</code>（默认 admin-only）。</li></ul><h2 id="前端登录态-预热与判定的边界" tabindex="-1">前端登录态：预热与判定的边界 <a class="header-anchor" href="#前端登录态-预热与判定的边界" aria-label="Permalink to &quot;前端登录态：预热与判定的边界&quot;">​</a></h2><ul><li><code>authStore</code> 持久化 key 为 <strong><code>zcontrol-auth-storage</code></strong>，字段含 <code>user / isAuthenticated / hasLoggedOut / autoLoginStatus</code>。<strong>token 不持久化</strong>，cookie 才是令牌载体。</li><li><code>autoLoginStatus</code> 虽持久化，但只代表上一次页面生命周期，唯一用途是让 <code>useSocket</code> 判断能否提前建连。</li><li><code>authResolved</code> <strong>不持久化</strong>，代表本次加载的鉴权引导终态。<code>RequireAuth</code> 只看它：未 resolved 时渲染 <code>null</code> 等待、不重定向；resolved 且未认证才跳 <code>/login</code>。别用持久化的 <code>done</code> 判断跳转——登出后该字段可能仍停在 <code>done</code>，首次访问者会被直接弹去登录页。</li><li>登出与会话失效统一走 <code>expireSession()</code>：清 user 并把 <code>autoLoginStatus</code> 重置回 <code>idle</code>，不可置 <code>done</code>。</li><li><strong>启动流程（AuthInitializer）</strong>：<code>GET /auth/me</code>（网络错误最多重试 8 次，间隔 2s）→ 失效则 <code>expireSession()</code> → 领取游客令牌（最多 3 次，退避 1.5s×n，仅 429 / 5xx / 网络错误重试）→ <code>reconnectSocket()</code>。终态必须置为 resolved。</li></ul><h2 id="连接降级与-401-拦截" tabindex="-1">连接降级与 401 拦截 <a class="header-anchor" href="#连接降级与-401-拦截" aria-label="Permalink to &quot;连接降级与 401 拦截&quot;">​</a></h2><ul><li><strong>Socket 三级降级</strong>（由 <code>connect_error</code> 触发）：错误命中鉴权类关键词时 <code>POST /auth/refresh</code>，成功重连（并发安全）→ refresh 失败则 <code>POST /auth/guest</code> 降级游客 → 游客也失败才 <code>logout()</code>。网络异常不登出，交给 socket.io 自动重试。</li><li><strong>HTTP 401/403 拦截</strong>（<code>apiFetch</code>）：自动 <code>refreshAccessToken()</code> 后带 <code>_retried</code> 标记重试一次；并发刷新复用同一 in-flight Promise；refresh 明确失败后置 <code>sessionExpired</code> 阻止级联重试，登录或领游客成功后重置。</li><li>媒体请求不走 <code>apiFetch</code>，播放引擎在 401/403 时单独触发刷新重试，见<a href="/advanced/video-pipeline">视频管线</a>。</li></ul><h2 id="接口权限分级" tabindex="-1">接口权限分级 <a class="header-anchor" href="#接口权限分级" aria-label="Permalink to &quot;接口权限分级&quot;">​</a></h2><ul><li><strong>公开</strong>：健康检查、注册模式与公开设置、注册与登录、游客令牌、B站图片代理；其余代理需登录，防带宽滥用。</li><li><strong>登录即可</strong>：挂载点、解析、代理、音乐、房间加入。</li><li><strong>房主 / root</strong>：房间删除、改名等房间级写操作。</li><li><strong>admin / root</strong>：管理后台读取；root-only 含用户审核、改角色、删用户、系统设置、更新、服务器文件。</li></ul><p>逐条标注见 <a href="/advanced/api">REST API 参考</a>。</p>`,27)])])}const p=o(c,[["render",a]]);export{g as __pageData,p as default};
